-- 0072 (M3-H game hardening) — POSTCHECK. READ ONLY: one SELECT, changes nothing.
-- Run once right after 0072. Every row must be ok = true.
-- On staging this runs as the read-only action "m3_0072_postcheck" of the Staging database workflow.
with checks(item, ok, detail) as (
  select 'join_match: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '47e042026bc084f8da0664020b77e1fb' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), 'missing')
  union all select 'leave_match: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '0bb6d58b5415a58c61878d0f4df230dd' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match'), 'missing')
  union all select 'decide_join: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '504c193753ecdda87b461204e1e0243f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), 'missing')
  union all select 'set_match_status: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '883dc68e447d0f8a5af681d8f395bf3b' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), 'missing')
  union all select 'update_match: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'efc91a08d70e84de15fced731b99a03c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), 'missing')
  union all select 'post_match: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '33b26aae02b8861858f86de235b66264' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), 'missing')
  union all select 'sync_match_with_booking: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '6d2108ade98ace105a863878e8bf9b3d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking'), 'missing')
  union all select 'match_message_notify: the 0072 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'c063c6d3f6071aa1a6446682cad26491' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), 'missing')
  union all select 'notify_waiting: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '147e1455408441356f06330b177952af' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'notify_waiting'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'notify_waiting'), 'missing')
  union all select 'remove_player: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '16aa48b9507019f62b35e77d4fb63763' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'remove_player'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'remove_player'), 'missing')
  union all select 'resolve_court: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'a1fb427e8c034c6fee12876f342d3460' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_court'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_court'), 'missing')
  union all select 'match_message_guard: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'd58b98d66bb5d8d5033a99069c411615' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_guard'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_guard'), 'missing')
  union all select 'push_text: new in 0072', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'b774b9226e3b8c68b25004b18d28289e' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'push_text'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'push_text'), 'missing')
  union all select 'chat insert guard: trigger match_messages_guard, before insert, enabled', exists (select 1 from pg_trigger where tgname = 'match_messages_guard' and tgrelid = 'public.match_messages'::regclass and tgenabled = 'O' and (tgtype & 2) = 2 and (tgtype & 4) = 4), ''
  union all select 'remove_player, resolve_court: signed-in users only', has_function_privilege('authenticated', 'public.remove_player(uuid,uuid)', 'execute') and not has_function_privilege('anon', 'public.remove_player(uuid,uuid)', 'execute') and has_function_privilege('authenticated', 'public.resolve_court(uuid,uuid)', 'execute') and not has_function_privilege('anon', 'public.resolve_court(uuid,uuid)', 'execute'), ''
  union all select 'notify_waiting: not callable through the API', not has_function_privilege('authenticated', 'public.notify_waiting(uuid)', 'execute') and not has_function_privilege('anon', 'public.notify_waiting(uuid)', 'execute'), ''
  union all select 'push_text: delivery role (service_role) only', has_function_privilege('service_role', 'public.push_text(uuid)', 'execute') and not has_function_privilege('authenticated', 'public.push_text(uuid)', 'execute') and not has_function_privilege('anon', 'public.push_text(uuid)', 'execute'), ''
  union all select 'game functions still callable by signed-in users (join, leave, decide, status, edit, post, hide)', (select bool_and(has_function_privilege('authenticated', p.oid, 'execute')) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('join_match','leave_match','decide_join','set_match_status','update_match','post_match','hide_match')), ''
)
select item, ok, detail from checks order by item;
